'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function allSplits(text, opts) {
  const ref = parse(text, opts);
  for (let i = 0; i <= text.length; i++) {
    for (let j = i; j <= text.length; j++) {
      const p = createParser(opts);
      const got = [...p.push(text.slice(0, i)), ...p.push(''), ...p.push(text.slice(i, j)), ...p.push(text.slice(j)), ...p.end()];
      assert.deepEqual(got, ref, JSON.stringify([text, i, j]));
    }
  }
  return ref;
}
function lineOf(fn) { try { fn(); } catch (e) { assert.ok(e instanceof SyntaxError, e); return e.message.match(/line (\d+)/)[1] | 0; } throw new Error('no throw'); }

assert.deepEqual(allSplits('\uFEFFa,"b""c"\r\n"x\r\ny",z\r'), [['a', 'b"c'], ['x\r\ny', 'z']]);
assert.deepEqual(allSplits('\n\n'), [[''], ['']]);
assert.deepEqual(allSplits('a\r\rb'), [['a'], [''], ['b']]);
assert.deepEqual(allSplits(''), []);
assert.deepEqual(allSplits('\uFEFF'), []);
assert.deepEqual(allSplits('a"b,"c\n'), [['a"b', 'c']]);
assert.deepEqual(allSplits('"",\uFEFF'), [['', '\uFEFF']]);
assert.deepEqual(allSplits('a;b,c', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(allSplits('😀,x\n'), [['😀', 'x']]);

// Immediate emission at CR before LF arrives.
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), Error);
assert.throws(() => createParser().push(1), TypeError);
for (const d of ['"', '\r', '\n', '', 'ab', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

assert.equal(lineOf(() => parse('a\r\n"x\r\ny\n" z')), 4);
assert.equal(lineOf(() => { const q = createParser(); q.push('"a\r'); q.push('\n"'); q.push('x'); }), 2);
assert.equal(lineOf(() => parse('a\n"b\rc')), 3);

assert.deepEqual(parse('x,x,__proto__\n1\n', { header: true }).map(o => ({ ...o })), [{ x: '1', x_2: '', ['__proto__']: '' }]);
assert.deepEqual(parse('', { header: true }), []);
console.log('ok');

